#!/usr/bin/env python3
"""
Round 189o (culprits), 8 October 2026. Needs round 188o.

Methane from 15 meat and dairy companies (Emissions Impossible: Methane
Edition) and Marine Sand Watch.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 189o (8 October)\n\nNeeds round 188o (guards on its heading). Tiles patch round189o_tiles.py\nbeside it. No app.js?v= bump.\n\n- methane_meat_dairy (route sitemap, tiles methane/meat_dairy.places.geojson\n  and .boxes.json, made by tiles meat_dairy_methane.py): the 15 companies of\n  Emissions Impossible: Methane Edition (IATP and Changing Markets\n  Foundation, 2022), from the report\'s dataset workbook the owner attached\n  (kept whole as tiles methane/emissions_impossible/dataset.json). The owner\n  says the authors agreed to its use. One point per company at its Wikidata\n  headquarters, sized by methane mass, meat #1A5C92 / dairy #6FC2DA, filter\n  Meat / Dairy. Each box holds every workbook row naming the company, under\n  its table\'s headings and units; the "read them" window holds every sheet\n  whole. Filed under Methane > Culprits (last), Nitrous oxide > Culprits >\n  Manure and grazing livestock, and Meat > Companies (new h5).\n- marine_sand_watch (route companion, unepgrid.ch/en/marinesandwatch) under\n  Oceans > Sand dredging (new h5). GRID-Geneva (Pascal Peduzzi) said\n  non-profits may use and integrate the platform but it does not share the\n  data. The platform itself opens from the globe on that page; its own\n  address was not visible from the sandbox.\n- Tiles medical_culprits.py: Alpha Therapeutic Corporation, which Wikidata\n  gives no place for, is placed at 5555 Valley Boulevard, Los Angeles (its\n  1987 letterhead, Infected Blood Inquiry document KDUD0000001), geocoded by\n  Nominatim at build time.\n- Replies: IEA Global Methane Tracker is CC BY 4.0 (credit IEA, mark\n  modifications "modified by ..."; no embedding the interactive map, no IEA\n  logo); its data needs a free IEA account download by the owner.\n  MethaneSAT asked what "raw data" means and offered its data request form\n  (files via Earth Engine / Google Cloud).\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round189o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 188o" not in h.read_text(encoding="utf-8"):
        sys.exit("round189o: round 188o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round189o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round189o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round189o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
